#include <string.h>
#include <stdlib.h>

MagickBooleanType WriteImages(const ImageInfo *image_info, Image *images, const char *filename, ExceptionInfo *exception) {
  if (image_info == NULL || images == NULL || filename == NULL || exception == NULL) {
    return MagickFalse;
  }

  if (strlen(filename) == 0) {
    return MagickFalse;
  }

  Image *image = images;
  Image *next_image = NULL;
  MagickBooleanType status = MagickTrue;

  while (image != NULL) {
    next_image = image->next;

    if (image->scene == 0) {
      char *output_filename = (char *)malloc(strlen(filename) + 1);
      if (output_filename == NULL) {
        return MagickFalse;
      }
      strcpy(output_filename, filename);

      ImageInfo *clone_info = CloneImageInfo(image_info);
      if (clone_info == NULL) {
        free(output_filename);
        return MagickFalse;
      }

      clone_info->filename = output_filename;
      clone_info->adjoin = MagickFalse;

      status = WriteImage(clone_info, image, exception);

      DestroyImageInfo(clone_info);
      free(output_filename);

      if (status == MagickFalse) {
        return MagickFalse;
      }
    }

    image = next_image;
  }

  return status;
}
